CREATE OR REPLACE FUNCTION public.create_ironhaus_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,email,phone,photo,account_type) VALUES(new.id,left(coalesce(new.raw_user_meta_data->>'full_name',''),100),coalesce(new.email,''),left(coalesce(new.raw_user_meta_data->>'phone',''),30),left(coalesce(new.raw_user_meta_data->>'photo',''),1500000),CASE WHEN new.raw_user_meta_data->>'account_type' IN ('owner','staff') THEN new.raw_user_meta_data->>'account_type' ELSE 'client' END); RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.can_read_image(path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.otp_verified() AND (split_part(path,'/',1)=auth.uid()::text OR (public.is_super_admin() AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.photo=path)) OR EXISTS(SELECT 1 FROM public.profiles p JOIN public.gym_records m ON m.client_id=p.id AND m.kind='members' WHERE p.photo=path AND public.gym_access(m.gym_id,'Members')) OR EXISTS(SELECT 1 FROM public.client_programs p WHERE p.user_id=auth.uid() AND p.definition::text LIKE '%'||path||'%') OR EXISTS(SELECT 1 FROM public.gym_records r WHERE public.gym_operational(r.gym_id) AND r.data::text LIKE '%'||path||'%' AND (public.gym_access(r.gym_id) OR r.kind IN ('gym','products','workouts','trainers')))) $$;
ALTER POLICY own_client_links ON public.client_gym_links USING (user_id=auth.uid() AND public.otp_verified()) WITH CHECK (user_id=auth.uid() AND public.otp_verified() AND public.client_has_gym_approval(gym_id));
ALTER POLICY own_membership_history ON public.client_membership_history USING (user_id=auth.uid() AND public.otp_verified());